CREATE TABLE public.profiles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', timezone text NOT NULL DEFAULT 'America/Sao_Paulo', height text NOT NULL DEFAULT '', weight text NOT NULL DEFAULT '', wake text NOT NULL DEFAULT '07:00', sleep text NOT NULL DEFAULT '23:00', "waterGoal" numeric NOT NULL DEFAULT 8, "sleepGoal" numeric NOT NULL DEFAULT 8, legacy_import_offered boolean NOT NULL DEFAULT false);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.appointments (id text NOT NULL, user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, title text NOT NULL, date text NOT NULL CHECK (date ~ '^\d{4}-\d{2}-\d{2}$'), time text NOT NULL CHECK (time ~ '^([01]\d|2[0-3]):[0-5]\d$'), description text NOT NULL DEFAULT '', category text NOT NULL CHECK(category IN ('trabalho','saude','estudos','pessoal','social','outro')), reminder integer NOT NULL DEFAULT 0, done boolean NOT NULL DEFAULT false, "createdAt" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.appointments TO authenticated; GRANT ALL ON public.appointments TO service_role; ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.entries (id text NOT NULL, user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, type text NOT NULL CHECK(type IN ('sono','alimentacao','exercicio','agua','outro')), date text NOT NULL CHECK(date ~ '^\d{4}-\d{2}-\d{2}$'), time text NOT NULL CHECK(time ~ '^([01]\d|2[0-3]):[0-5]\d$'), note text NOT NULL DEFAULT '', value numeric, quality text CHECK(quality IN ('ruim','ok','boa')), PRIMARY KEY(user_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.entries TO authenticated; GRANT ALL ON public.entries TO service_role; ALTER TABLE public.entries ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.habits (id text NOT NULL,user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('recorrente','pontual')),date text NOT NULL CHECK(date ~ '^\d{4}-\d{2}-\d{2}$'),time text NOT NULL CHECK(time ~ '^([01]\d|2[0-3]):[0-5]\d$'),note text NOT NULL DEFAULT '',PRIMARY KEY(user_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.habits TO authenticated; GRANT ALL ON public.habits TO service_role; ALTER TABLE public.habits ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.reminders(id text NOT NULL,user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE,name text NOT NULL,time text NOT NULL CHECK(time ~ '^([01]\d|2[0-3]):[0-5]\d$'),active boolean NOT NULL DEFAULT true,PRIMARY KEY(user_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.reminders TO authenticated; GRANT ALL ON public.reminders TO service_role; ALTER TABLE public.reminders ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.important_days(id text NOT NULL,user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE,name text NOT NULL,date text NOT NULL CHECK(date ~ '^(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$'),notify boolean NOT NULL DEFAULT true,PRIMARY KEY(user_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.important_days TO authenticated; GRANT ALL ON public.important_days TO service_role; ALTER TABLE public.important_days ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles(user_id) ON DELETE CASCADE,notifications boolean NOT NULL DEFAULT false,"weekStartsMonday" boolean NOT NULL DEFAULT false,compact boolean NOT NULL DEFAULT false,palette text NOT NULL DEFAULT 'menta' CHECK(palette IN ('menta','rosa','azul')),"largeText" boolean NOT NULL DEFAULT false,animations boolean NOT NULL DEFAULT true,"showSummary" boolean NOT NULL DEFAULT true,"calendarView" text NOT NULL DEFAULT 'mes' CHECK("calendarView" IN ('mes','semana')));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.preferences TO authenticated; GRANT ALL ON public.preferences TO service_role; ALTER TABLE public.preferences ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','appointments','entries','habits','reminders','important_days','preferences'] LOOP EXECUTE format('CREATE POLICY owner_select ON public.%I FOR SELECT TO authenticated USING (auth.uid() = user_id)',t); EXECUTE format('CREATE POLICY owner_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id)',t); EXECUTE format('CREATE POLICY owner_update ON public.%I FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id)',t); EXECUTE format('CREATE POLICY owner_delete ON public.%I FOR DELETE TO authenticated USING (auth.uid() = user_id)',t); END LOOP; END $$;
CREATE INDEX appointments_user_date ON public.appointments(user_id,date); CREATE INDEX entries_user_date ON public.entries(user_id,date); CREATE INDEX habits_user_date ON public.habits(user_id,date); CREATE INDEX important_days_user_date ON public.important_days(user_id,date); CREATE INDEX reminders_user_time ON public.reminders(user_id,time);
CREATE FUNCTION public.create_iagenda_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(user_id,name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'name','')); INSERT INTO public.preferences(user_id) VALUES(NEW.id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_iagenda_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER iagenda_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_iagenda_profile();
CREATE FUNCTION public.save_iagenda_data(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE owner uuid := auth.uid(); t text; key text; BEGIN IF owner IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
IF jsonb_typeof(payload) <> 'object' OR jsonb_typeof(payload->'profile') <> 'object' OR jsonb_typeof(payload->'prefs') <> 'object' THEN RAISE EXCEPTION 'Invalid data'; END IF;
UPDATE public.profiles SET name=payload->'profile'->>'name',timezone=COALESCE(payload->'profile'->>'timezone','America/Sao_Paulo'),height=payload->'profile'->>'height',weight=payload->'profile'->>'weight',wake=payload->'profile'->>'wake',sleep=payload->'profile'->>'sleep',"waterGoal"=(payload->'profile'->>'waterGoal')::numeric,"sleepGoal"=(payload->'profile'->>'sleepGoal')::numeric WHERE user_id=owner;
INSERT INTO public.preferences SELECT r.* FROM jsonb_populate_record(NULL::public.preferences,(payload->'prefs') || jsonb_build_object('user_id',owner)) r ON CONFLICT(user_id) DO UPDATE SET notifications=excluded.notifications,"weekStartsMonday"=excluded."weekStartsMonday",compact=excluded.compact,palette=excluded.palette,"largeText"=excluded."largeText",animations=excluded.animations,"showSummary"=excluded."showSummary","calendarView"=excluded."calendarView";
FOREACH t IN ARRAY ARRAY['appointments','entries','habits','reminders','important_days'] LOOP key := CASE WHEN t='important_days' THEN 'importantDays' ELSE t END; IF jsonb_typeof(payload->key) <> 'array' THEN RAISE EXCEPTION 'Invalid records'; END IF; EXECUTE format('DELETE FROM public.%I WHERE user_id=$1',t) USING owner; EXECUTE format('INSERT INTO public.%I SELECT r.* FROM jsonb_populate_recordset(NULL::public.%I, $1) r',t,t) USING (SELECT COALESCE(jsonb_agg(e || jsonb_build_object('user_id',owner)), '[]'::jsonb) FROM jsonb_array_elements(payload->key) e); END LOOP;
END $$;
REVOKE ALL ON FUNCTION public.save_iagenda_data(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_iagenda_data(jsonb) TO authenticated;